from pathlib import Path
import shutil, subprocess, sys
app=Path(sys.argv[1]); root=Path(__file__).resolve().parents[2]; work=Path.home()/'work'
out=app/'licenses'; out.mkdir(exist_ok=True)
for source,name in [(root/'LICENSE.md','platform-template-MIT.txt'),(root/'ps5/licenses/GPL-3.0.txt','GPL-3.0.txt'),
                    (work/'PS5_PayloadSDK/LICENSE','payload-sdk-LICENSE.txt'),
                    (work/'PS5_Vulkan/LICENSE','PS5-Vulkan-LICENSE.txt'),
                    (work/'PS5_Vulkan/.deps/work/radv-src/docs/license.rst','Mesa-license.rst')]:
    shutil.copy2(source,out/name)
kit_license=subprocess.check_output(['git','-C',str(work/'PS5_VKHomebrewUI'),'show','4451c261ac8631c698291ee765a37456f25bc22c:LICENSE'])
(out/'PS5-VKHomebrewUI-LICENSE.txt').write_bytes(kit_license)
shutil.copy2(root/'build-provenance.json',app/'build-provenance.json')
for name in ['GAME_README.md','REFERENCE-COMPARISON.md']:
    shutil.copy2(root/name,app/name)
(app/'THIRD_PARTY_NOTICES.txt').write_text('BattleStar PS5 combat prototype\n\nOriginal game and PNG artwork: futurepr0n/PSPGameCPP and futurepr0n/BattleStar-OSLib (reference d627d007e4d521b9b89cf38a13051c4bf9851ba9).\nReference audio: theme_battlestar_galactica.mp3; mrdeath_-_12th_moon_rising.xm (MrDeath). Music transcoded with FFmpeg to 48 kHz stereo Vorbis. Player cannon clips are original procedural sound design generated by ps5/synthesize_viper.py, inspired by Viper energy/cannon fire; no sampled television/game firing audio is used. Three 48 kHz stereo float-PCM variants include a twin-barrel micro-stagger. The original ViperFiring.wav is retained only in reference source assets and is no longer used by the game. Original asset rights remain with their respective owners; upstream does not supply a blanket asset licence.\nNew combat and audio integration: local PS5 port sources in PSPGameCPP/ps5.\nPS5 platform: KB-RPCS3 app, derived from Mihawk PS5 Vulkan Template and Sascha Willems Vulkan examples.\nUI/Vulkan renderer: BlackBearReloaded and Mihawk PS5_VKHomebrewUI (GPL-3.0-or-later).\nGraphics driver: Mesa/RADV PS5 port, Mihawk and Mesa contributors.\nToolchain and platform library: ps5-payload-dev and Mihawk PS5_PayloadSDK.\nThe original notices in the source files continue to apply. See licenses/ and assets/NOTICES.txt.\n')
